const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav'),langButton=document.querySelector('.language-toggle');
toggle?.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('.menu-label').textContent=open?'Cerrar':'Menú';toggle.querySelector('.material-symbols-outlined').textContent=open?'close':'menu';});
nav?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');toggle?.setAttribute('aria-expanded','false');if(toggle){toggle.querySelector('.menu-label').textContent='Menú';toggle.querySelector('.material-symbols-outlined').textContent='menu';}}));
langButton?.addEventListener('click',()=>{const isEnglish=document.documentElement.lang==='es';document.querySelectorAll('[data-t]').forEach(node=>{const key=node.dataset.t;if(!node.dataset.es)node.dataset.es=node.textContent;node.textContent=isEnglish?en[key]:node.dataset.es;});document.documentElement.lang=isEnglish?'en':'es';langButton.textContent=isEnglish?'ES':'EN';langButton.setAttribute('aria-label',isEnglish?'Cambiar a español':'Cambiar a inglés');document.title=isEnglish?'Alex Makes Products | Product, AI & Automation':'Alex Makes Products | Producto, IA y Automatización';});
document.querySelector('#year').textContent=new Date().getFullYear();
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduced&&'IntersectionObserver'in window){const sections=[...document.querySelectorAll('main .section')];sections.forEach(section=>section.classList.add('reveal'));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});sections.forEach(section=>observer.observe(section));const quick=[...document.querySelectorAll('.mobile-quick-nav a')];const navObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)quick.forEach(link=>link.classList.toggle('active',link.getAttribute('href')==='#'+entry.target.id))}),{rootMargin:'-35% 0px -55%'});sections.forEach(section=>navObserver.observe(section));}
